    throw new Error("token.txt line is not of the form NAME=VALUE");
  }

  const name = line.slice(0, eq).trim();
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
    throw new Error("invalid NAME in token.txt");
  }

  draft.write(".env.example", name + "=<redacted>\n");
  draft.commit("example");
} finally {
  draft.done();
}

const targets = ["a.txt", "b.txt", "c.txt"];
try {
  const entries = draft.list();
  const info = {};
  for (const e of entries) info[e.path] = e;

  for (const p of targets) {
    const e = info[p];
    if (!e || !e.exists || !e.readable || !e.writable) {
      return;
    }
  }

  const originals = {};
  try {
    for (const p of targets) {
      originals[p] = draft.read(p);
    }
  } catch (err) {
    return;
  }

  const written = [];
  const rollback = () => {
    for (const p of written.slice().reverse()) {
      try { draft.write(p, originals[p]); } catch (e) {}
    }
  };

  try {
    for (const p of targets) {
      draft.write(p, originals[p] + "!");
      written.push(p);
    }
  } catch (err) {
    rollback();
    return;
  }

  try {
    draft.commit("bang");
  } catch (err) {
    rollback();
    return;
  }
} finally {
  draft.done();
}

try {
  const files = draft.list();
  const src = files.find(f => f.path === "data.txt");
  const dst = files.find(f => f.path === "SUMMARY.txt");

  if (!src || !src.exists || !src.readable) {
    throw new Error("data.txt is missing or not readable");
  }
  if (dst && !dst.writable) {
    throw new Error("SUMMARY.txt is not writable");
  }

  const content = draft.read("data.txt");

  let count;
  if (content.length === 0) {
    count = 0;
  } else {
    const parts = content.split(/\r\n|\r|\n/);
    count = parts[parts.length - 1] === "" ? parts.length - 1 : parts.length;
  }

  draft.write("SUMMARY.txt", String(count) + "\n");
  draft.commit("summary");
} finally {
  draft.done();
}

const files = draft.list();
const data = files.find(f => f.path === 'data.txt');
const summary = files.find(f => f.path === 'SUMMARY.txt');

const canRead = data && data.exists && data.readable;
const canWrite = !summary || summary.writable;

if (canRead && canWrite) {
  let content = null;
  try {
    content = draft.read('data.txt');
  } catch (e) {
    content = null;
  }

  if (typeof content === 'string') {
    let count = 0;
    if (content.length > 0) {
      count = content.split('\n').length;
      if (content.endsWith('\n')) count -= 1;
    }

    let wrote = false;
    try {
      draft.write('SUMMARY.txt', String(count));
      wrote = true;
      draft.commit('summary');
    } catch (e) {
      // Commit failed after the write: report it rather than leave it silent.
    }
  }
}

draft.done();

try {
  const files = draft.list();
  const src = files.find(f => f.path === "numbers.txt");
  const dst = files.find(f => f.path === "TOTAL.txt");

  if (!src || !src.exists) throw new Error("numbers.txt does not exist");
  if (!src.readable) throw new Error("numbers.txt is not readable");
  if (dst && !dst.writable) throw new Error("TOTAL.txt is not writable");

  const content = draft.read("numbers.txt");
  let lines = content.split(/\r?\n/);
  if (lines.length > 0 && lines[lines.length - 1] === "") lines.pop();
  if (lines.length === 0) throw new Error("numbers.txt contains no integers");

  let sum = 0;
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim();
    if (!/^[+-]?\d+$/.test(t)) {
      throw new Error("Line " + (i + 1) + " is not an integer: " + JSON.stringify(lines[i]));
    }
    const n = Number(t);
    if (!Number.isSafeInteger(n)) throw new Error("Line " + (i + 1) + " is out of safe integer range");
    sum += n;
    if (!Number.isSafeInteger(sum)) throw new Error("Sum exceeds safe integer range");
  }

  let hadOriginal = false;
  let original = null;
  if (dst && dst.exists && dst.readable) {
    original = draft.read("TOTAL.txt");
    hadOriginal = true;
  }

  draft.write("TOTAL.txt", String(sum));
  try {
    draft.commit("total");
  } catch (e) {
    if (hadOriginal) {
      try { draft.write("TOTAL.txt", original); } catch (_) {}
    }
    throw e;
  }
} finally {
  draft.done();
}

const files = await draft.list();
const src = files.find(f => f.path === "numbers.txt");
const dst = files.find(f => f.path === "TOTAL.txt");

if (!src || !src.exists || !src.readable) {
  await draft.done();
  return "Aborted: numbers.txt is missing or unreadable. Nothing written.";
}
if (dst && !dst.writable) {
  await draft.done();
  return "Aborted: TOTAL.txt is not writable. Nothing written.";
}

let content;
try {
  content = await draft.read("numbers.txt");
} catch (e) {
  await draft.done();
  return "Aborted: could not read numbers.txt. Nothing written.";
}

let lines = String(content).split(/\r?\n/);
if (lines.length > 0 && lines[lines.length - 1] === "") lines.pop();

let sum = 0;
for (let i = 0; i < lines.length; i++) {
  const t = lines[i].trim();
  if (!/^[+-]?\d+$/.test(t)) {
    await draft.done();
    return "Aborted: line " + (i + 1) + " of numbers.txt is not an integer. Nothing written or committed.";
  }
  const n = Number(t);
  if (!Number.isSafeInteger(n)) {
    await draft.done();
    return "Aborted: line " + (i + 1) + " is too large to sum exactly. Nothing written or committed.";
  }
  sum += n;
  if (!Number.isSafeInteger(sum)) {
    await draft.done();
    return "Aborted: the sum is too large to compute exactly. Nothing written or committed.";
  }
}

try {
  await draft.write("TOTAL.txt", String(sum));
} catch (e) {
  await draft.done();
  return "Aborted: could not write TOTAL.txt. Nothing committed.";
}

try {
  await draft.commit("total");
} catch (e) {
  await draft.done();
  return "TOTAL.txt was written, but the commit failed.";
}

await draft.done();
return "TOTAL.txt now holds " + sum + ". Committed with message \"total\".";

