pub fn run(d: draft.Draft) -> draft.Done {
  let files = draft.list(d)
  let old_info = list.find(files, fn(f) { f.path == "old.txt" })
  let new_info = list.find(files, fn(f) { f.path == "new.txt" })

  let precheck = case old_info {
    Ok(info) ->
      case info.exists && info.readable && info.writable {
        True ->
          case new_info {
            Ok(n) ->
              case n.writable {
                True -> Ok(Nil)
                False -> Error(draft.NotWritable("new.txt"))
              }
            Error(_) -> Ok(Nil)
          }
        False ->
          case info.exists, info.readable {
            False, _ -> Error(draft.NotFound("old.txt"))
            True, False -> Error(draft.NotReadable("old.txt"))
            True, True -> Error(draft.NotWritable("old.txt"))
          }
      }
    Error(_) -> Error(draft.NotFound("old.txt"))
  }

  let outcome = {
    use _ <- result.try(precheck)
    use content <- result.try(draft.read(d, "old.txt"))
    use d1 <- result.try(draft.write(d, "new.txt", content))
    use d2 <- result.try(draft.write(d1, "old.txt", ""))
    draft.commit(d2, "move")
  }

