import gleam/list
import gleam/result

pub fn run(d: draft.Draft) -> draft.Done {
  let files = ["a.txt", "b.txt", "c.txt"]

  let outcome = {
    // Read every file up front; any unreadable/missing file aborts everything.
    use contents <- result.try(
      list.try_map(files, fn(path) {
        draft.read(d, path)
        |> result.map(fn(content) { #(path, content) })
      }),
    )

    // Apply all writes to a new draft; any failure aborts everything.
    use written <- result.try(
      list.try_fold(contents, d, fn(acc, pair) {
        let #(path, content) = pair
        draft.write(acc, path, content <> "!")
      }),
    )

    draft.commit(written, "bang")
  }

  case outcome {
    Ok(final) -> draft.done(final)
    // On any failure, hand back the untouched original draft.
    Error(_) -> draft.done(d)
  }
}

import draft
import gleam/int
import gleam/list
import gleam/result
import gleam/string

pub fn run(d: draft.Draft) -> draft.Done {
  let outcome = {
    use content <- result.try(draft.read(d, "data.txt"))
    let n = count_lines(content)
    use d1 <- result.try(draft.write(d, "SUMMARY.txt", int.to_string(n)))
    draft.commit(d1, "summary")
  }
  case outcome {
    Ok(d2) -> draft.done(d2)
    Error(_) -> draft.done(d)
  }
}

fn count_lines(content: String) -> Int {
  case content {
    "" -> 0
    _ -> {
      let n = list.length(string.split(content, "\n"))
      case string.ends_with(content, "\n") {
        True -> n - 1
        False -> n
      }
    }
  }
}

import draft
import gleam/int
import gleam/list
import gleam/result
import gleam/string

pub fn run(d: draft.Draft) -> draft.Done {
  let outcome = {
    use content <- result.try(
      draft.read(d, "numbers.txt")
      |> result.replace_error(Nil),
    )
    use nums <- result.try(parse(content))
    let total = int.sum(nums)
    use d2 <- result.try(
      draft.write(d, "TOTAL.txt", int.to_string(total))
      |> result.replace_error(Nil),
    )
    draft.commit(d2, "total")
    |> result.replace_error(Nil)
  }
  case outcome {
    Ok(final) -> draft.done(final)
    Error(_) -> draft.done(d)
  }
}

fn parse(content: String) -> Result(List(Int), Nil) {
  content
  |> string.split("\n")
  |> list.map(string.trim)
  |> list.filter(fn(line) { line != "" })
  |> list.try_map(int.parse)
}
